def transform(grid):
    # Move all non-background/non-border objects downward by five rows; preserve the solid color-2 boundary row.
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]
    for c, v in enumerate(grid[0]):
        out[0][c] = v
    # Objects are translated down five cells, clipped above the boundary.
    for r in range(1,h-1):
        for c,v in enumerate(grid[r]):
            if v:
                nr = r+5
                if nr < h-1:
                    out[nr][c] = v
    out[h-1] = grid[0][:]
    return out
