def transform(grid):
    h, w = len(grid), len(grid[0])
    if all(row[-1] != 0 and row[-1] == row[0] and all(x in (0,row[0]) for x in row) for row in grid):
        # uniform full bottom rail
        direction = 'down'
        rail = {(h-1,c) for c in range(w)}
    elif all(row[0] != 0 and row[0] == grid[0][0] for row in grid):
        # vertical rail at left
        direction = 'left'
        rail = {(r,0) for r in range(h)}
    elif all(v == grid[0][0] and v != 0 for v in grid[0]):
        direction = 'down'
        rail = {(0,c) for c in range(w)}
    else:
        return [row[:] for row in grid]
    dr,dc = ((1,0) if direction=='down' and min(r for r,c in rail)==0 else (1,0))
    # gravity points toward the full line: bottom if at bottom, otherwise top; left if left rail
    if direction=='down' and min(r for r,c in rail)==0: dr,dc=(-1,0)
    if direction=='down' and min(r for r,c in rail)!=0: dr,dc=(1,0)
    occupied=set(rail)
    out=[[0]*w for _ in range(h)]
    for r,c in rail: out[r][c]=grid[r][c]
    nonzero={(r,c):grid[r][c] for r in range(h) for c in range(w) if grid[r][c]!=0 and (r,c) not in rail}
    unseen=set(nonzero); components=[]
    while unseen:
        seed=next(iter(unseen)); color=nonzero[seed]; stack=[seed]; unseen.remove(seed); comp={seed}
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in unseen and nonzero[q]==color:
                    unseen.remove(q); comp.add(q); stack.append(q)
        components.append(comp)
    # Process shapes closest to rail first; then remaining pieces can settle against them.
    def dist(comp):
        return min((h-1-r if dr==1 else r if dr==-1 else c) for r,c in comp)
    components.sort(key=dist)
    for comp in components:
        shape=set(comp)
        while True:
            shifted={(r+dr,c+dc) for r,c in shape}
            if any(r<0 or r>=h or c<0 or c>=w for r,c in shifted) or shifted & occupied: break
            shape=shifted
        for r,c in shape: out[r][c]=nonzero[next(iter(comp))]
        occupied.update(shape)
    return out
