def transform(grid):
    h,w=len(grid),len(grid[0])
    # Determine the monochrome rail. The shapes are translated along its axis
    # and compacted in order toward the rail, keeping each object's footprint.
    if all(row[0] == grid[0][0] != 0 for row in grid):
        axis='h'; direction=1; rail=0
    elif len(set(grid[0]))==1 and grid[0][0]!=0:
        axis='v'; direction=1; rail=0
    else:
        return [row[:] for row in grid]
    cells={(r,c):grid[r][c] for r in range(h) for c in range(w) if grid[r][c]!=0 and not ((axis=='h' and c==rail) or (axis=='v' and r==rail))}
    unseen=set(cells); comps=[]
    while unseen:
        seed=next(iter(unseen)); color=cells[seed]; todo=[seed]; unseen.remove(seed); comp={seed}
        while todo:
            r,c=todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in unseen and cells[q]==color:
                    unseen.remove(q); comp.add(q); todo.append(q)
        comps.append((color,comp))
    # Process foremost pieces first, then stack pieces behind without overlap.
    def order(item):
        return min(c for r,c in item[1]) if axis=='h' else min(r for r,c in item[1])
    comps.sort(key=order)
    occupied={(r,c) for r in range(h) for c in range(w) if (axis=='h' and c==0) or (axis=='v' and r==0)}
    results=[]
    for color,comp in comps:
        shape=set(comp)
        while True:
            nxt={(r+(1 if axis=='v' else 0),c+(1 if axis=='h' else 0)) for r,c in shape}
            if any(r<0 or r>=h or c<0 or c>=w for r,c in nxt) or nxt & occupied:
                break
            shape=nxt
        results.append((color,shape)); occupied.update(shape)
    out=[[0]*w for _ in range(h)]
    if axis=='h':
        for r in range(h): out[r][0]=grid[r][0]
    else:
        out[0]=grid[0][:]
    for color,shape in results:
        for r,c in shape: out[r][c]=color
    return out
