    # shift rigidly along that line's perpendicular toward the rail.
    if all(row[-1] == 2 for row in grid):
        direction = 'right'
        rail = {(r, w-1) for r in range(h)}
    elif all(row[0] == 2 for row in grid):
        direction = 'left'
        rail = {(r, 0) for r in range(h)}
    elif all(v == 2 for v in grid[0]):
        direction = 'down'
        rail = {(0, c) for c in range(w)}
    else:
        return [row[:] for row in grid]
    cells = {(r,c):grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in rail}
    remaining=set(cells); components=[]
    while remaining:
        p=next(iter(remaining)); color=cells[p]; comp={p}; todo=[p]; remaining.remove(p)
        while todo:
            r,c=todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in remaining and cells[q]==color:
                    remaining.remove(q); comp.add(q); todo.append(q)
        components.append((color,comp))
    if direction=='right':
        dr,dc=0,1; key=lambda comp: max(c for r,c in comp); reverse=True
    elif direction=='left':
        dr,dc=0,-1; key=lambda comp: min(c for r,c in comp); reverse=False
    else:
        dr,dc=1,0; key=lambda comp: min(r for r,c in comp); reverse=False
    components.sort(key=lambda item:key(item[1]), reverse=reverse)
    occupied=set(rail); moved=[]
    for color,comp in components:
        shape=set(comp)
        while True:
            nxt={(r+dr,c+dc) for r,c in shape}
            if any(r<0 or r>=h or c<0 or c>=w for r,c in nxt) or nxt & occupied:
