def transform(grid):
    h, w = len(grid), len(grid[0])
    # Determine the direction indicated by the solid color-2 edge; same-colored
    # connected shapes slide rigidly toward that edge until they meet a shape.
    if all(x == 2 for x in grid[0]):
        direction = (1, 0); rail = {(0,c) for c in range(w)}
    elif all(x == 2 for x in grid[-1]):
        direction = (-1, 0); rail = {(h-1,c) for c in range(w)}
    elif all(row[0] == 2 for row in grid):
        direction = (0, 1); rail = {(r,0) for r in range(h)}
    elif all(row[-1] == 2 for row in grid):
        direction = (0, -1); rail = {(r,w-1) for r in range(h)}
    else:
        return [row[:] for row in grid]
    dr, dc = direction
    values = {(r,c): grid[r][c] for r in range(h) for c in range(w)
              if grid[r][c] != 0 and (r,c) not in rail}
    unseen = set(values); objects = []
    while unseen:
        seed = next(iter(unseen)); color = values[seed]
        comp = {seed}; stack = [seed]; unseen.remove(seed)
        while stack:
            r,c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in unseen and values[q] == color:
                    unseen.remove(q); comp.add(q); stack.append(q)
        objects.append((color, comp))
    if dc == 1: dist = lambda comp: min(c for r,c in comp)
    elif dc == -1: dist = lambda comp: min(w-1-c for r,c in comp)
    elif dr == 1: dist = lambda comp: min(r for r,c in comp)
    else: dist = lambda comp: min(h-1-r for r,c in comp)
    objects.sort(key=lambda item: dist(item[1]))
    occupied = set(rail); moved = []
    for color, comp in objects:
        shape = set(comp)
        while True:
            nxt = {(r+dr,c+dc) for r,c in shape}
            if any(r<0 or r>=h or c<0 or c>=w for r,c in nxt) or nxt & occupied:
                break
            shape = nxt
        occupied.update(shape); moved.append((color, shape))
    out = [[0]*w for _ in range(h)]
    for r,c in rail: out[r][c] = 2
    for color, shape in moved:
        for r,c in shape: out[r][c] = color
    return out
