    elif all(v == 2 for v in grid[-1]):
        dr, dc = -1, 0
        rail = {(h - 1, c) for c in range(w)}
    elif all(row[-1] == 2 for row in grid):
        dr, dc = 0, 1
        rail = {(r, w - 1) for r in range(h)}
    elif all(row[0] == 2 for row in grid):
        dr, dc = 0, -1
        rail = {(r, 0) for r in range(h)}
    else:
        return [row[:] for row in grid]
    cells = {(r,c):grid[r][c] for r in range(h) for c in range(w)
             if grid[r][c] != 0 and (r,c) not in rail}
    unseen = set(cells)
