            r,c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in unseen and cells[q] == color:
                    unseen.remove(q); comp.add(q); stack.append(q)
        objects.append((color, comp))
    # Resolve from the far side toward the rail so each piece lands against
