def transform(grid):
    h,w=len(grid),len(grid[0])
    # Treat every contiguous same-color orthogonal component as a rigid piece;
    # each piece falls toward the solid top rail, in simultaneous gravity steps.
    rail={(0,c) for c in range(w)}
