        while todo:
            r,c=todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in unseen and cells[q]==col:
                    unseen.remove(q);piece.add(q);todo.append(q)
        pieces.append((col,piece))
    occupied=set(rail)
    # Process lower pieces first; they settle first and support pieces above.
    pieces.sort(key=lambda p:max(r for r,c in p[1]),reverse=True)
    placed=[]
    for col,piece in pieces:
        shape=set(piece)
        while True:
            moved={(r+1,c) for r,c in shape}
            if any(r>=h for r,c in moved) or moved & occupied: break
            shape=moved
        occupied.update(shape);placed.append((col,shape))
    out=[[0]*w for _ in range(h)]
    for r,c in rail:out[r][c]=2
    for col,piece in placed:
        for r,c in piece:out[r][c]=col
    return out
