def transform(grid):
    h,w=len(grid),len(grid[0])
    # gravity moves the rigid objects toward the boundary line
    # If boundary is top: pack each colored component up independently.
    if all(v==2 for v in grid[0]):
        out=[[0]*w for _ in range(h)];out[0]=grid[0][:]
        # translate connected components toward top, stopping on other pieces
        vals={(r,c):grid[r][c] for r in range(1,h) for c in range(w) if grid[r][c]}
        unseen=set(vals); comps=[]
        while unseen:
            p=min(unseen); col=vals[p]; comp={p}; stack=[p];unseen.remove(p)
            while stack:
                r,c=stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in unseen and vals[q]==col:unseen.remove(q);comp.add(q);stack.append(q)
            comps.append((col,comp))
        comps.sort(key=lambda x:min(r for r,c in x[1]))
        occ={(0,c) for c in range(w)}
        for col,comp in comps:
            shape=set(comp)
            while True:
                nxt={(r-1,c) for r,c in shape}
                if any(r<0 for r,c in nxt) or nxt&occ:break
                shape=nxt
            occ|=shape
            for r,c in shape:out[r][c]=col
        return out
    # rail on left/right: compact cells within each row, preserving order
    if all(row[0]==2 for row in grid):
        out=[[0]*w for _ in range(h)]
        for r in range(h):
            out[r][0]=2; vals=[v for v in grid[r][1:] if v]
            out[r][1:1+len(vals)]=vals
        return out
    if all(row[-1]==2 for row in grid):
        out=[[0]*w for _ in range(h)]
        for r in range(h):
            out[r][-1]=2; vals=[v for v in grid[r][:-1] if v]
            for i,v in enumerate(vals):out[r][w-2-i]=v
        return out
    return [row[:] for row in grid]
