    elif all(row[0] == 2 for row in grid):
        dr, dc, rail = 0, -1, {(r, 0) for r in range(h)}
    elif all(row[-1] == 2 for row in grid):
        dr, dc, rail = 0, 1, {(r, w - 1) for r in range(h)}
    else:
        return [row[:] for row in grid]

    cells = {(r, c): grid[r][c] for r in range(h) for c in range(w)
             if grid[r][c] and (r, c) not in rail}
    unseen = set(cells)
    pieces = []
    while unseen:
        seed = min(unseen)
        color = cells[seed]
        comp = {seed}
        stack = [seed]
        unseen.remove(seed)
        while stack:
            r, c = stack.pop()
            for q in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if q in unseen and cells[q] == color:
                    unseen.remove(q)
                    comp.add(q)
                    stack.append(q)
        pieces.append((color, comp))

    def distance(comp):
        if dr == 1:
            return min(r for r, c in comp)
        if dr == -1:
            return h - 1 - max(r for r, c in comp)
        if dc == 1:
            return min(c for r, c in comp)
        return w - 1 - max(c for r, c in comp)

    # Closest pieces settle first and support the pieces behind them.
    pieces.sort(key=lambda item: distance(item[1]))
    occupied = set(rail)
    placed = []
    for color, comp in pieces:
        shape = set(comp)
        while True:
            shifted = {(r + dr, c + dc) for r, c in shape}
            if any(not (0 <= r < h and 0 <= c < w) for r, c in shifted) or shifted & occupied:
                break
            shape = shifted
        occupied.update(shape)
        placed.append((color, shape))

    out = [[0] * w for _ in range(h)]
    for r, c in rail:
        out[r][c] = 2
    for color, shape in placed:
        for r, c in shape:
            out[r][c] = color
    return out
